"""第61項：真正SDK＋設定頁同步／重試；所有雲端HTTP由隔離回應器接住。"""
from pathlib import Path
from playwright.sync_api import sync_playwright
import json,re,os
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'production/qa/evidence/redesign/game-unification'
f=json.loads((ROOT/'.local-online/unify-game/fixtures.json').read_text())['full']
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 c=b.new_context(viewport={'width':390,'height':844},device_scale_factor=2,reduced_motion='reduce')
 c.route('**/*.supabase.co/**',lambda route:route.abort())
 c.add_init_script('''(()=>{const f='''+json.dumps(f,ensure_ascii=False)+''';localStorage.setItem('jianghu_life_v1_ls',JSON.stringify({version:1,savedAt:Date.now(),state:f.state}));localStorage.setItem('jianghu_ancestry_v1',JSON.stringify(f.meta));localStorage.setItem('jianghu_ancestry_saved_at_v1',String(Date.now()));window.__syncWrites=[];window.__syncFail=false;window.__syncHold=false;window.__boardHold=false;const user={id:'00000000-0000-4000-8000-000000000061',aud:'authenticated',role:'authenticated',is_anonymous:true,email:'',app_metadata:{provider:'anonymous',providers:['anonymous']},user_metadata:{},created_at:new Date().toISOString()};const encode=v=>btoa(JSON.stringify(v)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');const token=encode({alg:'HS256',typ:'JWT'})+'.'+encode({sub:user.id,role:'authenticated',aud:'authenticated',exp:Math.floor(Date.now()/1000)+3600})+'.qa_only_signature';const answer=(body,status=200)=>new Response(status===204?null:JSON.stringify(body),{status,headers:{'Content-Type':'application/json'}});const fetch=window.fetch.bind(window);window.fetch=async(input,options={})=>{const url=String(input?.url??input);if(!url.includes('.supabase.co'))return fetch(input,options);if(url.includes('/auth/v1/signup'))return answer({access_token:token,refresh_token:'qa-only-refresh',expires_in:3600,token_type:'bearer',user});if(url.includes('/auth/v1/user'))return answer(user);if(url.includes('/rest/v1/saves')&&options.method==='POST'){__syncWrites.push(JSON.parse(options.body));if(__syncHold)await new Promise(resolve=>window.__releaseSync=resolve);return __syncFail?answer({message:'qa isolated failure'},503):answer(null,204)}if(url.includes('/rest/v1/leaderboard_live')){if(options.method==='POST')return answer(null,204);if(__boardHold)await new Promise(resolve=>window.__releaseBoard=resolve);return answer(Array.from({length:30},(_,i)=>({user_id:user.id+'-'+i,name:'驗收俠客'+i,jianghu_rank:42+i,cult_tier:2,cult_xp:100-i,age:18})))}if(url.includes('/rest/v1/life_scores'))return answer([{user_id:user.id,name:'驗收俠客',score:99,cult_tier:2,age:18}]);return answer([])}})();''')
 p=c.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.goto(os.getenv('UNIFICATION_CLOUD_BASE','http://127.0.0.1:5295/'))
 p.get_by_role('button',name=re.compile('^續寫前緣')).click();p.wait_for_timeout(250)
 if p.get_by_role('button',name='領受',exact=True).count():p.get_by_role('button',name='領受',exact=True).click()
 p.get_by_role('button',name='開啟設定',exact=True).click();d=p.get_by_role('dialog',name='設定',exact=True)
 now=d.get_by_role('button',name='立即同步',exact=True);now.wait_for();p.wait_for_function("!document.querySelector('.ink-cloud-actions button').disabled")
 # 首次上傳完成後先故意製造一次HTTP失敗，再用新按鈕重試。
 now.click();p.wait_for_function("document.querySelector('[aria-label=\"帳戶與存檔\"]').textContent.includes('已同步')")
 p.evaluate('__syncFail=true');now.click();retry=d.get_by_role('button',name='重試同步',exact=True);retry.wait_for()
 p.evaluate('__syncFail=false;__syncHold=true;__syncWrites=[]');retry.click();working=d.get_by_role('button',name='同步中……',exact=True);working.wait_for();assert working.is_disabled();working.evaluate('e=>{e.click();e.click()}');p.wait_for_timeout(150);assert p.evaluate('__syncWrites.length')==1
 p.evaluate('__syncHold=false;__releaseSync()');p.wait_for_function("document.querySelector('[aria-label=\"帳戶與存檔\"]').textContent.includes('已同步')")
 payload=p.evaluate('__syncWrites[0].payload');assert payload['life']['character']['name']==f['state']['character']['name'];assert json.loads(payload['ancestry'])['jade']==f['meta']['jade']
 assert d.get_by_role('textbox',name='電郵（綁定或換機登入）',exact=True).count();p.screenshot(path=str(OUT/'cloud-synced-390.png'));assert d.get_by_role('button',name='關閉設定').evaluate('e=>e.getBoundingClientRect().top>=0')
 d.get_by_role('button',name='開江湖榜',exact=True).click();board=p.get_by_role('dialog',name='排行榜',exact=True);board.locator('.ink-board-list').wait_for();assert '第 42 位' in board.inner_text()
 p.evaluate('__boardHold=true');board.get_by_role('tab',name='修為境界',exact=True).click();board.get_by_text('翻閱榜單中……',exact=True).wait_for();assert '第 42 位' not in board.inner_text();p.wait_for_function('Boolean(window.__releaseBoard)');p.evaluate('__boardHold=false;__releaseBoard()');board.locator('.ink-board-list').wait_for();assert '修為 100' in board.inner_text()
 board.locator('.ink-settings-content').evaluate('e=>e.scrollTop=e.scrollHeight');assert board.get_by_role('button',name='關閉排行榜').evaluate('e=>e.getBoundingClientRect().top>=0');board.get_by_role('tab',name='一生總結',exact=True).click();board.get_by_text('99 分',exact=True).wait_for();board.get_by_role('tab',name='一生總結',exact=True).click();assert board.get_by_text('99 分',exact=True).is_visible();p.screenshot(path=str(OUT/'leaderboard-390.png'));assert not errors,errors
 (OUT/'cloud.json').write_text(json.dumps({'realSupabaseSdk':True,'isolatedHttpResponses':True,'noExternalWrites':True,'manualLatestSnapshot':True,'failedUploadRetry':True,'disabledWhileUploading':True,'doubleClickSingleUpload':True,'ancestryIncluded':True,'settingsAndBoardHeadersFixed':True,'switchBoardClearsStaleNumbers':True,'sameBoardTabKeepsRows':True,'pageerrors':errors},ensure_ascii=False,indent=2)+'\n');print('GAME_UNIFICATION_CLOUD_PASS');c.close();b.close()
